class NomEstructuraEscalar extends BaseNomEstructuraEscalar {
	
	/**
     * Obtener un listado de los datos de las estructuras escalares dado un identificador de tarifa de concepto.
     * 
     * @param int $idtarifaconcepto  	Identificador de la tarifa de concepto.
     * @return array Listado de los datos de las estructuras escalares.
     */
    public static function obtenerListadoEstructurasEscalares($idtarifaconcepto) {
	    //Devolviendo el listado de estructuras escalares en forma de arreglo.
        return Doctrine_Query::create()
				->select('ee.idestructuraescalar, ee.denominacion, ee.idtipocampo,tc.denominacion as denomtipocampo, 
				ee.idnomencladorreferencia, nr.denominacion as denomnomenclador, ee.nivel, ee.idtipoentrada, te.denominacion as denomtipoentrada,
				ee.idconfreportescertificaciones, rc.denominacion as denomreporte, 
				ee.idvariablesconfreportescertificaciones, vrc.denominacion as denomvarreporte, ee.idconceptopdtarifa')
				->from('NomEstructuraEscalar ee')
				->leftjoin('ee.NomTipoCampo tc')
				->leftjoin('ee.NomNomencladorReferencia nr')
				->leftjoin('ee.NomTipoEntrada te')
				->leftjoin('ee.ConfReportesCertificaciones rc')
				->leftjoin('ee.ConfVariablesReportesCertificaciones vrc')
                ->where('ee.idconceptopdtarifa = ?', array($idtarifaconcepto))
                ->fetchArray();
    }
    
    public static function obtenerListadoEstructurasEscalaresTipoEntradaPersonaCargo($idtarifaconcepto) {
