				ee.idnomencladorreferencia, nr.denominacion as denomnomenclador, ee.nivel, ee.idtipoentrada, te.denominacion as denomtipoentrada,
				ee.idconfreportescertificaciones, rc.denominacion as denomreporte, 
				ee.idvariablesconfreportescertificaciones, vrc.denominacion as denomvarreporte, ee.idconceptopdtarifa')
				->from('NomEstructuraEscalar ee')
				->leftjoin('ee.NomTipoCampo tc')
				->leftjoin('ee.NomNomencladorReferencia nr')
				->leftjoin('ee.NomTipoEntrada te')
				->leftjoin('ee.ConfReportesCertificaciones rc')
				->leftjoin('ee.ConfVariablesReportesCertificaciones vrc')
                ->where('ee.idconceptopdtarifa = ? and (ee.idtipoentrada = 4 or ee.idtipoentrada = 3)', array($idtarifaconcepto))
                ->fetchArray();
    }
	
