   public static function existeDenomEstructuraEscalarIdConcepto($denominacion, $idconceptopdtarifa) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomEstructuraEscalar p')
                ->where('denominacion = ? and idconceptopdtarifa = ?', array($denominacion, $idconceptopdtarifa))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }
   
